const b = $input.first().json.body ?? $input.first().json;
const all = b.findings || [];
const urgent = all.filter(f => f.severity === 'critical' || f.severity === 'high');
const icon = { critical: '🚨', high: '⚠️', medium: '🔎', low: '•' };

const lines = urgent.slice(0, 8).map(f =>
  `${icon[f.severity]} [${f.score}] ${f.name} (${f.platform}${f.source === 'simulated' ? ', simulated' : ''})\n   ${f.summary}\n   ${f.url || ''}`
);

const message = urgent.length
  ? `BrandGuard alert for ${b.brand}\n${urgent.length} high-risk impersonation(s) found of ${b.stats?.flagged ?? all.length} flagged.\n\n${lines.join('\n\n')}`
  : `BrandGuard scan for ${b.brand}: no high-risk findings (${b.stats?.flagged ?? 0} low/medium flagged).`;

const top = urgent[0];
const abuseSubject = top ? `Impersonation report: "${top.name}" impersonating ${b.brand}` : '';
const abuseBody = top
  ? `Hello Trust & Safety team,\n\nWe represent ${b.brand} and are reporting an account/app that impersonates our brand and may be used to defraud customers.\n\nReported item: ${top.name}\nPlatform: ${top.platform}\nURL: ${top.url}\nRisk score: ${top.score}/100 (${top.severity})\nWhy we believe it is impersonation: ${top.summary}\nIndicators: ${(top.signals || []).join('; ')}\n${(top.phones || []).length ? 'Unofficial phone numbers listed: ' + top.phones.join(', ') + '\n' : ''}\nWe ask that you review and remove it under your impersonation / fraud policy. Evidence is available on request.\n\nThank you,\n${b.brand} Brand Protection`
  : '';

return [{ json: {
  ok: true,
  brand: b.brand,
  scannedAt: b.scannedAt,
  totalFlagged: b.stats?.flagged ?? all.length,
  urgentCount: urgent.length,
  hasUrgent: urgent.length > 0,
  message,
  abuseSubject,
  abuseBody,
  topFinding: top ? { name: top.name, platform: top.platform, url: top.url, score: top.score } : null
} }];
